export default function parseFeedback(inputs) {
  if (typeof inputs.completion !== "string") throw new Error("The classifier did not return text.");
  const text = inputs.completion.trim().replace(/^```(?:json)?\s*\n?([\s\S]*?)\n?```$/i, "$1");
  let reply;
  try {
    reply = JSON.parse(text);
  } catch {
    // Retain the source's repair for literal newlines inside JSON strings.
    reply = JSON.parse(text.replace(/\n(?=[^"]*"(?:[^"]*"[^"]*")*[^"]*$)/g, "\\n"));
  }
  if (
    !reply ||
    typeof reply !== "object" ||
    Array.isArray(reply) ||
    typeof reply.category !== "string" ||
    !reply.category.trim()
  )
    throw new Error("The classifier must return a category string.");
  const category = reply.category.trim().toLowerCase();
  const known = ["success-story", "urgent-issue", "ticket"].includes(category);
  const instruction = typeof reply.instruction === "string" ? reply.instruction : "";
  if (instruction.length > 2000 || (known && !instruction.trim()))
    throw new Error("A routed instruction must contain 1–2000 characters.");
  return { category, instruction, feedback: inputs.feedback, status: known ? "routed" : "ignored" };
}
